import { HelpBody } from './helpContent';

/**
 * The help catalog in Spanish.
 *
 * <p>A file per language: a translation pass is then reviewable on its own, and eighteen articles
 * in five languages inline would be one literal nobody could edit without breaking a quote. A key
 * that is missing here falls back to the English body, visibly — see `bodyFor`.</p>
 */
export const ES: Readonly<Record<string, HelpBody>> = {
  "phrases": {
    title: "Phrases: las frases que deja de reescribir",
    whatItIs: "Una lista de frases que usted guarda, como botones en la sección **Phrases** del panel. Pulse una y pasa al portapapeles; la pega donde iba a escribirla, normalmente en el cuadro de Claude Code. La lista se edita en una pestaña propia: **ConnectOtherAIs: Edit phrases**.",
    why: "Algunas instrucciones se escriben varias veces al día — *haz un pull request, acéptalo, despliega, comprueba que funciona*. Volver a escribirlas no es trabajo, es fricción, y una frase reescrita de memoria es una frase que va cambiando.\n\n**Copia en lugar de escribir en el cuadro por usted, y eso fue una decisión, no un atajo.** Claude Code no tiene ninguna orden que acepte texto arbitrario: la que sí acepta un prompt solo rellena una conversación NUEVA, nunca aquella en la que usted está. Quedaba una pulsación sintética a través de la API de Windows — solo Windows, cerca de un segundo, y nunca medida en ese sentido. Un `Ctrl+V` es mejor precio que un mecanismo que puede fallar en silencio en la máquina de otra persona.",
    setup: "**Edit phrases** desde la sección *Phrases* del panel o desde la paleta de comandos. Pulse **Add a phrase**, dele un nombre para el botón y escriba la frase en el cuadro grande. Todo se guarda un instante después de que deje de escribir.\n\nEl nombre es solo una etiqueta; al portapapeles va la frase misma. Deje el nombre vacío y el botón llevará la primera línea de la propia frase.",
    usage: "La sección **Phrases** muestra un botón por frase. Púlselo, pegue, siga trabajando. La lista es solo suya: nunca se envía a `coai-mcp` ni se refleja en un Team server, y es la misma lista en ambos lados con *This side* activado — una frase que usted escribió no es una propiedad de la máquina donde la escribió.\n\nUna frase se guarda exactamente como la escribió, espacios y saltos de línea incluidos: un fragmento indentado se pega indentado.",
    whatCanGoWrong: "**Una fila sin texto se descarta.** El nombre es la etiqueta y el texto es la cosa, así que una fila sin nada dentro no es una frase. Una fila que usted escribió mal en `settings.json` se descarta por sí sola y el resto de la lista sigue funcionando: perder todas las frases por una equivocada sería el fallo peor.\n\n**Un guardado que no llega lo dice, y dice por qué.** La pestaña conserva lo que usted escribió y muestra el motivo del rechazo con las palabras de quien lo rechazó, en vez de redibujar la lista sin sus palabras. El motivo más frecuente es una ventana que no se ha puesto al día con una actualización: VS Code sigue conociendo solo los ajustes que registró al abrirse la ventana, así que una frase no se puede guardar hasta que la recargue — y la línea dice justo eso, con el botón que lo hace.\n\n**Nada se pulsa por usted.** La frase llega al portapapeles y se detiene ahí; pegarla, y enviarla, siguen siendo suyas.",
  },
  "notifications": {
    title: "Notifications: todo lo que la extensión le ha dicho",
    whatItIs: "Una página con todos los mensajes que ConnectOtherAIs ha mostrado en su pantalla, conservados después de que el aviso desapareciera: qué decía, cuándo, desde dónde, qué hacer al respecto y cuántas veces ha ocurrido. La sección **Notifications** del panel dice cuántos son nuevos y la abre.",
    why: "Un mensaje que usted no estaba mirando es un mensaje que nunca ocurrió. El 16-09-2026 un rol borrado a las 19:05 siguió siendo revisado durante once rondas, porque el espejo de ajustes se había detenido a las 18:27 y lo dijo exactamente una vez, en un aviso que nadie vio. Noventa minutos del día de una persona se fueron en averiguarlo. Ahora cada mensaje entra primero en un archivo y después en la pantalla, para que la respuesta a «¿qué decía?» esté en otro sitio que no sea la memoria de alguien.",
    setup: "Nada que configurar. Esta extensión escribe en `notifications.jsonl`, en la misma carpeta de datos que todo lo demás. La página también lee `server-notices.jsonl` al lado, donde escribirá el servidor MCP: esa mitad aún no está construida, así que hoy, en una instalación en uso, el archivo sencillamente no existe. Mover esa carpeta los mueve con ella.",
    usage: "La sección **Notifications** del panel dice cuántos hay desde la última vez que miró y abre la página. En ella, una pestaña por TIPO — un fallo, un rechazo, una parada, una tormenta, una pregunta que usted respondió — y una fila por cosa ocurrida, por muchas veces que haya ocurrido.\n\n**Una fila es un fallo, no una aparición.** Si algo salió mal cuatrocientas veces, eso es una fila que dice cuatrocientas, con la rapidez con que llegaron al lado. Ordene por cualquier columna; los vacíos van al final en ambos sentidos, así que un ritmo que no pudo medirse nunca sube arriba. La búsqueda encuentra cualquier palabra de la fila, incluido el propio mensaje.\n\nAbrir la página marca como leídos los registros que cargó. **Con un filtro puesto no marca nada** — tres filas en pantalla no deben afirmar que se leyeron tres mil — y la línea sobre la tabla dice cuál de las dos cosas está pasando. **Mark everything read** es el botón para un historial que no piensa recorrer hacia atrás.",
    whatCanGoWrong: "**Un fallo repetido está acotado y lo dice, en vez de fingir.** Una misma cosa puede registrarse mil veces en una ejecución de la ventana; a partir de ahí el archivo se detiene y la fila se lee *1000+*, nunca un número que nadie puede saber. Tres ventanas que llegan cada una a ese punto se muestran como *1000+ in each of 3 runs*, porque tres ventanas con problemas no son un incidente tres veces mayor.\n\n**La página muestra los últimos miles de registros, no el archivo.** Cuando hay más antiguos lo dice, y siguen sin leer hasta que usted vaya a ellos o pulse **Mark everything read**.\n\n**Un recuento que no pudo leerse lo dice en lugar de mostrar cero.** «Todavía no se ha escrito nada», «no se pudieron leer las notificaciones» y «nada nuevo» son tres frases distintas a propósito: una lectura rota que aparece como un cero limpio es lo que enseña a una persona a dejar de fiarse de un contador — y este existe porque a alguien se le escapó un mensaje.\n\n**Los secretos se quitan a la entrada.** Una contraseña, un token o una clave en una URL o en un mensaje de error se sustituyen antes de que la línea llegue al archivo, y el archivo conserva todo lo demás. En una misma máquina pueden existir dos carpetas de datos, una para Windows y otra para WSL; la página nombra la que está leyendo, porque «está vacía» y «está mirando la otra» son problemas distintos.",
  },
  "your-own-roles": {
    title: "Roles propios: revisar algo que no es código",
    whatItIs: "Un rol de revisión es un revisor con una pregunta. Este producto trae cinco: crítica del plan, convenciones, arquitectura, seguridad y fiabilidad, rendimiento y UX-DX. **Los roles que usted añade son suyos**, con nombres en su idioma y las preguntas que usted quiere que se hagan.\n\nLa puerta a su alrededor no cambia. Las mismas rondas, el mismo umbral, los mismos hallazgos con las mismas categorías, el mismo veredicto. Lo que cambia es qué se le pregunta a un revisor, y eso es el prompt que usted escribe.",
    why: "Los cinco que vienen de fábrica son los cinco que quiere un programador. Quien contrasta requisitos con una especificación, lee currículos o repasa la descripción de un producto antes de publicarla necesita otra pregunta, y nadie puede preverlas todas de antemano. Por eso es una lista que usted edita y no una lista que nosotros entregamos.",
    setup: "**Edit roles…** en la sección *Prompts per round* abre la página de roles. Añada un rol, póngale nombre y escriba su prompt general: la pregunta que se hace cuando no se ha elegido otra cosa. Añada más prompts para preguntas más estrechas; en *Prompts per round* se ofrecen uno por ronda.\n\nLos cinco roles de fábrica están en esa misma página. Puede reescribir el texto de cualquiera de sus prompts y añadirles prompts propios; no puede renombrarlos, moverlos a la otra etapa ni borrar lo que traen, porque sus nombres ya son claves en sus ajustes, en las sesiones abiertas y en cada ronda registrada, y el servidor de revisión no lee ninguna de esas cosas de su configuración: una página que le dejara cambiarlas mostraría algo que ninguna ronda hará.\n\n**El identificador se genera por usted** y se muestra bajo el nombre. Así se llama su rol en el ajuste, en el archivo de sesión y en la base de datos, de modo que después no cambia: renombre el rol tantas veces como quiera.\n\n**Como mucho cinco roles activos por etapa.** Un sexto no se puede marcar; desactive uno antes, y un rol que añada cuando ya hay cinco activos nace desactivado: lo que la página muestra es lo que se ejecutará. Un rol desactivado permanece en esta página con todo lo que usted escribió en él.",
    usage: "Todo en la página se guarda un momento después de que deje de escribir. El TEXTO de un prompt se escribe en un archivo junto a sus demás datos de coai, que es de donde el servidor siempre ha leído las sustituciones de prompts: un prompt reescrito sobrevive a una actualización, y borrar el archivo devuelve lo que el producto trae.\n\n**Un rol para algo que no es una tarea de programación** se guarda y se muestra, y todavía no participa en ninguna ronda: la etapa que revisa un documento en lugar de un diff aún se está construyendo. La página lo dice en el propio rol.\n\n**Quitar un rol pregunta primero** y se lleva consigo los prompts que usted escribió en él: la fila se puede volver a teclear, los párrafos de debajo no.",
    whatCanGoWrong: "**Un `coai-mcp` anterior a 0.19.0 no lee sus roles en absoluto.** Es la versión que aprendió a hacerlo: por debajo, los roles están en el panel y en ninguna ronda — nada falla y nada lo dice, por lo que la página muestra un aviso con la versión que usted tiene. Actualice el servidor en **MCP server**.\n\n**Un Team server ejecuta los roles que configuró su operador.** Trae los mismos cinco y su operador puede añadir más: `Coai:ExtraRoles` en el servidor, o `Coai:AllowAnyRole` para aceptar cualquier identificador de rol VÁLIDO. El panel pregunta a cada servidor configurado qué roles ejecuta y lo dice junto al rol, ANTES de una ronda en lugar de en su resultado. Un servidor demasiado antiguo para que se le pregunte, o uno al que no se pudo llegar, sigue ejecutando los cinco de fábrica; y la frase dice cuál de los dos casos ocurrió, porque uno se arregla actualizando un servidor y el otro mirando la red.\n\n**Dos lados, dos conjuntos de roles.** Con *This side* activado, sus roles pertenecen al lado en el que trabaja, como las rondas y los umbrales. Los archivos de prompt no: una pregunta que usted escribió es una pregunta, la haga donde la haga.",
  },
  "chat-with-other-ai": {
    title: "Chat with other AI: preguntar a un segundo modelo sobre un pasaje",
    whatItIs: "Seleccione un párrafo en la respuesta de su asistente y pulse `Ctrl+Alt+A`: se abre una pestaña donde el modelo de otro proveedor lo explica en su idioma, y la conversación puede continuar. En el menú contextual lo mismo está como dos entradas, y cada una dice lo que hará: **CoAI: default** pregunta de inmediato al modelo marcado como main, y **CoAI: choose** deja el turno en el campo de texto — puede cambiar el modelo o el prompt y pulsar Enter usted mismo. Las teclas siguen obedeciendo el ajuste **When to send**, que una entrada de menú no puede mostrar.\n\nTambién funciona en un archivo corriente — `.md`, `.cs`, cualquiera que pueda abrir. Seleccione un fragmento y pulse las mismas teclas, o use el clic derecho. Allí la selección se lee directamente del editor en vez de copiarse por el portapapeles: es inmediato y su portapapeles queda intacto. Sin selección se envía el archivo entero, y si el archivo es grande se pregunta antes. La conversación lleva el nombre del archivo, y una segunda pregunta sobre el mismo archivo continúa la misma conversación.\n\n**CoAI: take the question** es lo mismo para una pregunta que Claude Code le hace a USTED. Su cuadro de preguntas no se puede seleccionar, no hay nada que copiar: la pregunta se lee del archivo de sesión, con cada opción y cada descripción, y va al campo de texto. Se niega en vez de adivinar: si la última pregunta ya fue respondida lo dice, y si dos sesiones de esta carpeta están esperando lo nombra en lugar de elegir una.",
    why: "Una respuesta densa en inglés no siempre es clara, y pedirle una explicación al mismo modelo devuelve las mismas palabras. Otro proveedor la lee sin prejuicios. A mano son cinco pasos — seleccionar, copiar, pasar al navegador, chat nuevo, pegar — varias veces por hora; aquí es una tecla, y la respuesta se queda en el editor.",
    setup: "Nada, si ya hay un revisor activo en el runtime `antigravity`: ese es el que responde en un chat, y se usa el primero que puede salvo que nombre otro. Cuatro ajustes son suyos: el prompt con el que viaja el pasaje (por defecto la palabra `Explain`), el idioma de la respuesta (inglés por defecto, y deliberadamente no el de estas páginas), con qué modelo ABRE una pestaña nueva y si se envía de inmediato. El modelo ya no es solo un ajuste: la pestaña tiene su propio selector, y lo que elija allí pertenece a esa conversación y no a todas las futuras. **CoAI: add the question** es el mismo lector con el otro verbo: añade la pregunta a lo que ya hay en el campo de escritura en lugar de sustituirlo, así el turno que acaba de componer conserva su instrucción y gana la pregunta debajo como más material.\n\n**Edit chat presets** abre una pestaña con ambas listas, y todo allí se guarda mientras escribe. Desde que existen los presets, aquel prompt único son **sus prompts guardados, cada uno con un nombre** — uno marcado como el principal, que es el que viaja cuando una captura se envía sola. Al lado están **sus modelos guardados, cada uno con un nombre** y, si quiere, un prompt con el que abrir el cuadro. Lo que hubiera escrito en el antiguo prompt único se convirtió en su primer preset con nombre la primera vez que esta versión lo leyó, así que nada se perdió.\n\n**En la barra lateral, *What to ask about the selection* ya es un selector.** Nombra tus prompts guardados en lugar de guardar una copia de uno, y **Edit presets…** al lado abre la pestaña donde se editan las palabras mismas: ya no hay dónde discrepen. Vacío significa el marcado como principal. *Which model answers* hace las mismas dos preguntas que la pestaña: primero el proveedor y luego uno de sus modelos — y un segundo campo vacío significa el modelo al que está configurada la propia fila del revisor.",
    usage: "La combinación de teclas copia la selección por usted y después hace lo que diga su ajuste **When to send**: preguntar enseguida, o dejar el turno en el campo de escritura. Los dos elementos del menú contextual no lo consultan — cada uno dice en su propio nombre lo que hará. Copiar por usted el menú tampoco puede: cerrar ese menú saca la selección del panel, así que toma lo último copiado. Por eso el pasaje se muestra arriba de la pestaña: se ve qué va a preguntarse. Una pestaña por sesión del asistente, para que dos conversaciones nunca se mezclen.\n\n**El cuadro de escritura se queda donde está** y la conversación se desplaza por encima. Solo se salta a una respuesta nueva si usted ya estaba abajo: si sube a leer algo, nada le arrastra, y **Jump to newest ↓** le devuelve cuando quiera. El cuadro crece mientras escribe hasta cerca de un tercio de la ventana, y solo entonces se desplaza. Enter envía, Shift+Enter es una línea nueva, y hay un botón **Send** para quien prefiera pulsar. A su lado, **✕ vacía el cuadro** de una pulsación, y cada control ± de arriba lleva ahora su icono — una lupa para el tamaño del texto, un sol para su tono — para que cuatro botones idénticos seguidos dejen de ser un orden que haya que recordar.\n\n**Las respuestas se componen, no se vuelcan**: títulos, listas numeradas y con viñetas, tablas, código. Los enlaces son azules, y lo que abren está acotado: una ruta DENTRO de este espacio de trabajo abre ese archivo en el editor, una dirección `http` o `https` abre el navegador, y todo lo demás se queda en texto: una ruta que sale del espacio de trabajo, una URL `file://` y una dirección que el modelo solo mencionó en una frase en vez de escribirla como enlace. Un archivo que no se encuentra lo dice, en vez de no hacer nada. Sus propias palabras van a la derecha, cada respuesta lleva el nombre del modelo que la dio, en el color de ese modelo, y una línea la cierra, de modo que el final de una respuesta larga se encuentra. **Copy answer** le da la respuesta entera como Markdown, y **Copy block** — debajo de cada bloque de código y cada cita — le da solo ese bloque. Si un modelo termina con una respuesta que le propone enviar, y la abre como un bloque ```reply, el control de ese bloque dice **Copy the reply prompt**. La extensión reconoce únicamente esa etiqueta: lo que hace que un modelo la escriba es su propio prompt, nunca algo añadido a sus espaldas.\n\n**El selector pide primero el proveedor y luego uno de sus modelos**, porque una lista de modelos pertenece a un proveedor. Cambiar a mitad de la conversación está previsto — el hilo entero viaja con usted — y junto al selector está lo que esta conversación lleva costado. Sobre el cuadro hay dos filas de presets: sus modelos en el color de su proveedor, el mismo que ese proveedor lleva en todo lo demás aquí, y sus prompts en un color que ningún proveedor tiene, para que un prompt nunca pueda confundirse con un proveedor. **Un botón está encendido solo mientras sus palabras son la instrucción vigente.** Elija un modelo a mano en las dos listas, o borre la instrucción del cuadro, y el botón que la puso se apaga; el rol que añade un preajuste de modelo cuenta igual, por eso vaciar el cuadro apaga los dos.\n\n**Un cuadro vacío con otro modelo elegido es volver a preguntar**: la misma pregunta va al otro modelo llevándose la conversación menos la respuesta que no quiso, y el botón dice de quién es el turno antes de que pulse. **Pegue una captura de pantalla** en el cuadro y viajará con la siguiente pregunta. **Stop** aparece mientras corre un turno y termina el turno para el que fue dibujado, nunca el siguiente.\n\n**Asked** está arriba a la derecha, junto a los controles ±, y muestra lo que USTED escribió en la sesión de Claude Code de la que salió esta pestaña. Al cabo de unas horas la pregunta con la que empezó el trabajo se ha ido hacia arriba y la ventana ya no sabe decir de qué trata — y uno acaba preguntándole al asistente en qué está trabajando. Las palabras nunca se fueron: esto las lee del archivo de sesión, emparejado con esta pestaña por su propio título para que dos sesiones en una carpeta no se confundan nunca, y las fija encima de la conversación, donde el desplazamiento no las alcanza. `‹` y `›` recorren cada uno de sus turnos, del más antiguo al más reciente. Púlselo otra vez y se pliega, en medio segundo y no de golpe. Una pestaña abierta desde un archivo no tiene sesión detrás, así que no tiene botón.\n\n**Carry nothing above** está en la última respuesta. Al pulsarlo se dibuja debajo una línea naranja de trazo y punto: a partir de ahí, un modelo al que cambie y un servidor de equipo — al que se le entrega la conversación entera en CADA turno — reciben solo lo que está por debajo de la línea. No se borra nada: la conversación se queda entera donde está y puede desplazarla y copiarla como antes.\n\nNo es «olvida esto», es «no lleves esto más allá»: el modelo local con el que habla guarda la conversación en su propio proceso y conserva cada palabra. Lo que ahorra es lo otro — un cambio de modelo que si no lanzaría diez turnos sobre un tema a un modelo al que pregunta por otro, y un servidor de equipo que le cobraría esos diez turnos bajo cada pregunta siguiente.\n\nPúlselo de nuevo más abajo y el punto se traslada allí. No hay nada que deshacer: la marca es una posición, no un estado, y solo se dibuja la vigente. Sobrevive a recargar la ventana junto con la conversación.\n\n**CoAI: switch conversations…** es la lista de todas ellas. `Ctrl+Shift+Alt+G` (`Cmd+Shift+Alt+G` en un Mac), el menú contextual o la paleta de comandos. Arriba **Open**: lo que esta ventana tiene ahora mismo en una pestaña, con el modelo, cuántos turnos lleva y lo último que se dijo en ella; debajo **Recent**: todo lo demás, lo más reciente primero. Escribir filtra por el título, por el modelo que respondió y por esa última línea, así que una conversación que recuerda por una palabra de su respuesta está a una palabra. Elegir una abierta trae su pestaña al frente. Elegir una cerrada la abre de nuevo donde se quedó: la conversación entera, sin nada en marcha hasta que pregunte, y esa primera pregunta lleva la conversación al modelo que la responda.\n\n**Una papelera en cada fila cerrada** olvida esa conversación, y `Alt+Supr` (`Cmd+Supr` en un Mac) olvida la conversación bajo el cursor. La lista sigue abierta en ambos casos, así que limpiar cinco son cinco pulsaciones y no cinco aperturas de la lista. Una conversación abierta no tiene papelera: cierre antes su pestaña. **El globo del título** ensancha la lista de esta carpeta a todas las carpetas y vuelve, y el título siempre dice cuál de las dos está viendo.\n\n**Olvidar no es destruir.** La fila desaparece de inmediato y ninguna lista vuelve a mostrarla, pero la transcripción se aparta en el disco y solo se borra de verdad tras los mismos noventa días que todo lo demás: una tecla pulsada sobre la fila equivocada no le cuesta una conversación.\n\n**CoAI: go to conversation** es el camino inverso, y normalmente el que se quiere. `Ctrl+Alt+G` (`Cmd+Alt+G` en un Mac), el menú contextual o la paleta: se pulsa en la pestaña en la que está trabajando, no en una lista. Si esta ventana ya tiene esa conversación abierta, pasa al frente. Si solo está guardada, se abre de nuevo y queda ligada a esa pestaña, de modo que cada pulsación posterior llega al mismo sitio. Si no hay nada guardado para la pestaña, la lista se abre con **New conversation** bajo el cursor, y no se crea nada hasta que la pulse, porque un atajo es fácil de pulsar sin querer. Al pulsarla se abre el **Chat with other AI** de siempre para esa pestaña, a partir de lo que tenga seleccionado en ella. Y desde un terminal, el panel Output o cualquier sitio donde una conversación no pueda pertenecer, se abre la lista completa en lugar de no hacer nada.\n\n**New chat**, en la cabecera de la pestaña, vuelve a empezar en la misma pestaña. La conversación en la que estaba se archiva — está entera en **CoAI: switch conversations…** con el mismo nombre — y la pestaña vuelve a ser suya, vacía, y la cita con la que empezó la anterior queda retirada. El modelo, el prompt y el nombre de la pestaña se quedan como estaban, y la siguiente pregunta llega a un modelo que no ha oído nada de ello. De eso se trata: una conversación larga sobre un asunto es un modelo que sigue cargando con él cuando usted pregunta por otro, y en un servidor de equipo es además la conversación entera reenviada y facturada con cada pregunta. Si hay un turno en marcha, primero se termina y se espera, de modo que la respuesta que estaba esperando se queda en la conversación archivada. El botón del aviso «esta conversación está llena» es el mismo.\n\n**Donde no puede estar seguro, pregunta.** Dos sesiones de Claude con el mismo nombre, o una conversación sobre este archivo guardada en otra carpeta de la misma ventana, abren la lista reducida a ellas, con un título que dice por qué, y con el nombre de la propia pestaña ya escrito en el buscador, de modo que lo que busca suele estar arriba. Un retroceso muestra otra vez todo. **Y si exactamente una conversación guardada se abrió desde una pestaña de ese nombre — y ahora hay exactamente una pestaña abierta con él —, abre esa en lugar de preguntar**: donde tiene una respuesta la usa, y donde solo tiene una conjetura, le enseña la conjetura.",
    whatCanGoWrong: "Copiar la selección requiere una sesión de Windows: la de esta máquina o — desde una ventana WSL — aquella a la que esa ventana está conectada. En los demás casos la tecla lo dice y le remite al menú, que funciona en todas partes. Si no se puede alcanzar al ayudante, o arranca y no termina, el mensaje lo nombra en vez de culpar a su selección. Si el proceso del modelo muere, la respuesta siguiente avisa de que la conversación volvió a empezar. Un revisor en otro runtime se rechaza por su nombre, en lugar de faltar en silencio. Recargar la ventana conserva lo DICHO: cada pestaña de chat abierta vuelve con sus preguntas y respuestas, y una línea que dice que la recarga cerró la conversación. El modelo detrás ya no está — nada corre hasta que vuelva a preguntar, y esa primera pregunta lleva la transcripción a una sesión nueva: eso es lo que cuesta — o, si ha marcado la conversación, solo lo que está por debajo de la marca.\n\n**Una imagen se rechaza POR SU NOMBRE en vez de enviarse al vacío.** `codex` se rechaza como NO PROBADO, no como incapaz: su cuenta llegó a un límite de uso a mitad de la medición, y eso es una frase distinta de un no medido. Un revisor en un servidor Team todavía no tiene sitio para una imagen en el cable. Un SVG se rechaza aunque sea una imagen: es marcado con script dentro, y lo que se hace aquí es entregar un archivo a un proceso que va a abrirlo.\n\n**El total en curso lleva tilde de aproximación en dos proveedores de tres.** Solo `claude` informa de lo que cobró; en los demás la cifra se deduce de los tokens, y un turno estimado hace que todo el total sea una estimación. El registro exacto, turno a turno, está en **Show review rounds**: una conversación también es una fila de ese registro. Y sube: una pregunta a un servidor de equipo lleva consigo la conversación entera, así que un hilo largo allí es más lento y más caro que uno corto. El remedio es **Carry nothing above**, sin perder el hilo — o capturar un pasaje nuevo.\n\n**Una conversación que la lista ofrece puede haber desaparecido ya.** La lista se construye en segundo plano y se mantiene en memoria — para que se abra al instante en lugar de leer miles de archivos mientras usted espera —, de modo que otra ventana puede olvidar una conversación entre el momento en que la lista se dibuja y el momento en que usted la pulsa. Entonces se lo dice y retira la fila, en vez de abrir una pestaña sobre nada. Una conversación que SÍ está y no se puede leer es otra frase distinta y conserva su fila: una carpeta que no respondió, o un registro escrito por una versión más nueva de esta extensión, no han perdido nada y volverán a abrirse cuando puedan.\n\n**Una conversación abierta en otra ventana de VS Code aparece en la lista, pero no puede abrirse aquí.** Su fila lo dice, y al pulsarla se le indica dónde está. Una ventana no puede traer otra al frente, y una segunda pestaña sobre una misma conversación le daría dos escritores que se sobrescriben entre sí, y acabaría partida en dos. Cambie a esa ventana. Por la misma razón no puede olvidarse desde aquí: la pestaña que la tiene volvería a escribirla.",
  },
  "the-consultant": {
    title: "El consultor: un segundo proveedor para una IA atascada",
    whatItIs: "Una herramienta, `consult`, que su asistente llama ÉL MISMO cuando lleva dos vueltas alrededor del mismo fallo. Entrega el problema al modelo de otro proveedor junto con esta copia de trabajo y los cambios que aún no ha confirmado, y ese modelo lee el árbol SÓLO EN LECTURA y responde con un consejo.\n\nNada de lo que diga se aplica. La respuesta vuelve dentro de una valla y marcada como consultiva, al asistente se le dice con todas las letras que es una opinión sobre código que el consultor no puede tocar, y la corrección se sigue escribiendo y verificando aquí. Es una conversación y no una pregunta: unos pocos turnos, para que el segundo modelo pueda decir «pruebe esto y dígame qué imprimió» — y oír la respuesta.",
    why: "Dos rondas de la misma corrección equivocada es lo más caro que hace un asistente, y el modelo que produjo el punto ciego es precisamente el que no puede verlo. Otro proveedor lee el mismo árbol sin ideas previas.\n\nA mano esto significa describir el problema otra vez a una segunda IA — sin el repositorio, sin el diff y normalmente sin lo que ya se intentó —, que es por lo que la segunda respuesta es tantas veces la primera. Aquí el servidor reúne las tres partes por su cuenta: el asistente envía sólo el problema con sus propias palabras.",
    setup: "**Let a stuck AI consult another vendor** es el interruptor, en la sección **Consultant**. Está encendido y no hace nada hasta que un asistente pregunta.\n\nDebajo, una fila por cada clase de llamante, porque a quién pregunta una IA atascada depende de qué IA se ha atascado. De fábrica: Claude Code pregunta a `codex`, Codex a `claude`, Gemini y todo lo demás a `codex` — nunca a sí mismos.\n\n**Se ofrece el mismo catálogo que en *Add a reviewer***, con los mismos nombres: `Codex (OpenAI)`, `Antigravity (Google)`, `Claude`. Una entrada que no puede mantener una conversación aparece debajo con su razón, en vez de faltar en silencio; un servidor de equipo no se ofrece en absoluto — una consulta nunca sale por uno.\n\n**Estos son los ajustes PROPIOS del consultor.** La segunda casilla es el modelo, y vacío significa el predeterminado de ese runtime; al lado, donde el runtime lo tiene, están su propio endpoint y la ruta a su CLI. Un proveedor aquí comparte solo el nombre — y por tanto su clave en el almacén — con la fila de revisor del mismo nombre, y nada más: cambie el modelo o el endpoint de un revisor y el consultor se queda donde usted lo puso, y borre ese revisor y el consultor sigue funcionando.\n\nAlgo que la sección dice en lugar de ocultar: un consultor en la CLI de Codex con endpoint propio — DeepSeek, OpenRouter, uno suyo — puede guardarse y **no puede ejecutarse en esta versión**. El servidor lo rechaza por su nombre, y la fila lo advierte donde usted elige. Una fila que, desde una versión anterior, sigue apuntando a un revisor de servidor de equipo dice lo mismo y deja de ofrecer ajustes que nunca podrá usar. La última entrada de la lista es **Another OpenAI-compatible endpoint**: pide un nombre y una URL base, igual que *Add a reviewer*, y el nombre es la clave con la que sus credenciales quedan en la entrada del baúl.\n\nElegir el proveedor del propio llamante está permitido, y la fila dice qué pensar de ello: solo merece la pena con un modelo más fuerte, porque el servidor ve qué proveedor pregunta y nunca su modelo.",
    usage: "Usted no pulsa nada. El fragmento en su `CLAUDE.md` le dice al asistente cuándo recurrir a esto — el mismo fallo dos veces, o usted diciendo que sigue sin arreglarse — y llama la herramienta solo.\n\nTres números lo acotan. **Turns per consultation** es cuántas veces puede preguntarse una consulta, cinco por defecto, y al consultor se le DICE en cada turno cuántos quedan, para que el último responda en vez de hacer una aclaración más. **Calls per session** es cuántas consultas puede abrir una sesión, diez por defecto. **Close an idle consultation after, minutes** cierra el hilo que nadie retomó; una pregunta posterior es entonces una consulta nueva con todo el presupuesto.\n\n**Mientras una consulta está en curso se ve en la barra lateral**, arriba de la sección *Consultant*: quién pregunta a quién, por qué turno va y el aviso sobre el árbol de trabajo si saltó. Cuando termina, desaparece — la barra lateral es presente — y cada consulta que ha habido es una fila en **Show review rounds**, pestaña *Consultations*: en qué estaba atascado, qué se aconsejó y cuánto costó.\n\nNo puede haber ping-pong: una pregunta ya hecha en esta consulta se rechaza, en el turno que fuera, así que el siguiente turno sólo ocurre después de que su asistente haya probado algo de verdad y tenga qué contar. Lo que costó cada una está en **Show review rounds**.",
    whatCanGoWrong: "**El consultor no puede escribir en su repositorio, y el servidor comprueba en lugar de fiarse.** Toma una huella del árbol antes y después, y una consulta DURANTE LA CUAL el árbol haya CAMBIADO se da por fallida y se informa, en vez de responderse: la comprobación ve que algo se movió, nunca quién lo movió, así que su propia edición mientras esperaba también la activa. Nunca borra ni revierte lo que encuentra: un archivo que usted escribió mientras esperaba es suyo, y perderlo por una comprobación de seguridad sería peor que aquello para lo que existe la comprobación.\n\n**Un consejo es material, no una instrucción.** Llega dentro de una valla que dice qué proveedor lo escribió y que es sólo consultivo, de modo que un texto del repositorio dirigido a una IA no consigue que se le obedezca por el hecho de leerse en voz alta a la suya.\n\n**La conversación vive en el almacén del otro proveedor**, que es lo que hace posible una repregunta, y contiene los cambios sin confirmar de este repositorio. Ese es el precio de la función y no nos corresponde borrarlo. Apague la función y la herramienta rechaza POR SU NOMBRE, de modo que al asistente se le dice que está apagada en vez de dejarlo adivinando.",
  },
  "install-the-server": {
    title: "Empiece aquí: instale el servidor MCP",
    whatItIs: "La extensión es la cara. Quien hace la revisión es `coai-mcp`, un programa pequeño que arranca su asistente de IA. Mientras no esté instalado, no revisa nadie.",
    why: "Una revisión tiene que ejecutarse donde está su código, lanzar las CLI de los proveedores y trabajar durante minutos. Una extensión de VS Code no puede hacerlo, y un servidor propiedad de una ventana de VS Code moriría con ella.",
    setup: "Abra la sección **Server**. Ahí se ve qué hay instalado, qué hay publicado, y un botón cuando difieren: púlselo. La descarga se verifica contra el `.sha256` de la propia release, el binario va al almacén privado de la extensión y no entra en el `PATH`.\n\nDespués, menú ⋯ → **Copy the MCP config block** y pegue el bloque en la configuración de su asistente. Esto se hace UNA vez. Reinicie el asistente para que levante el servidor.",
    usage: "Después volverá poco a la sección Server: la versión publicada se reconsulta como mucho cada media hora, y **Check again** pregunta ahora mismo.\n\nCada plataforma tiene su propio binario. En cada release se publican compilaciones para Windows, macOS y Linux; una máquina sin la suya lo dice con franqueza en vez de descargar la ajena.",
    whatCanGoWrong: "Si el panel dice que no pudo leer la versión publicada, no se alcanzó GitHub. Nada está roto: el servidor instalado funciona.\n\nSi tras pegar el bloque su asistente no muestra las herramientas, no se ha reiniciado. El bloque lleva la ruta exacta al binario; un bloque copiado de otra máquina apunta a una ruta que aquí no existe.",
  },
  "choose-reviewers": {
    title: "Después: elija quién revisa",
    whatItIs: "La sección **Reviewers** es el panel de modelos ajenos que leerá su plan y su código. Cada fila es un proveedor: una casilla para incluirlo, un selector de modelo, un ▶ para abrir su CLI en una terminal, un ⤓ para instalar esa CLI, un ⟳ que se pone verde cuando hay publicada una versión más nueva, sus dos precios por millón de tokens — y junto a cada precio, la etapa que paga: **reviews plans** junto a la tarifa de entrada, **reviews code** junto a la de salida. Después **remove**.\n\nUna fila de servidor de equipo no tiene aquí precios donde ponerlas, porque su CLI corre en el servidor y su precio es la suscripción de la empresa: sus dos casillas de etapa van en una línea propia.",
    why: "Todo el sentido está en que el revisor no es el autor. Una segunda opinión del mismo modelo que escribió el código vale menos que una primera opinión de otro — y dos proveedores que coinciden en un hallazgo son la señal más fuerte que produce este producto.",
    setup: "**＋ Add a reviewer** ofrece los proveedores que conoce esta compilación: Codex, Antigravity (Gemini, Claude y GPT-OSS con una sola suscripción), un segundo Claude, DeepSeek, OpenRouter y una fila en blanco para cualquier endpoint compatible con OpenAI.\n\nLa mayoría se autentican solos: si la CLI está conectada en esta máquina, no hace falta clave. El ▶ de una fila abre una terminal con esa CLI — ahí la conecta, y ahí su propio comando de consumo ya está escrito esperando Enter. El ⤓ abre la misma terminal con el comando de INSTALACIÓN — el oficial del proveedor, para el sistema operativo en el que esa terminal realmente se ejecuta. VS Code conectado a WSL recibe el comando de Linux, no el de PowerShell.",
    usage: "**⟳ le dice si hay algo que actualizar antes de pulsarlo.** Verde significa que el proveedor publica una versión más nueva que la de esta máquina; gris, que ya tiene la más nueva o que no se pudo leer alguno de los dos números. Ambos están en la ayuda emergente, así que el color nunca es la única señal. Al pulsarlo se abre una terminal con el mismo comando que usa ⤓, porque en todas estas CLI volver a ejecutar el instalador ES la actualización: OpenAI imprime una sola línea bajo *Install Codex* y bajo *Update Codex*, la instalación nativa de Anthropic es el mismo script, y `agy` no tiene subcomando de actualización.\n\nDos revisores es el mínimo útil, porque la señal es la coincidencia. Tres cuestan el triple y rara vez dicen el triple.\n\nEl selector de modelo muestra a qué llega de verdad esa CLI en esta máquina: en Codex, su propia caché de modelos; en los demás, una lista curada. **another model…** acepta cualquier id exacto.",
    whatCanGoWrong: "Quitar al último revisor se rechaza: un panel sin nadie no revisa nada.\n\nUn proveedor cuya CLI no está instalada lo dice en **providers** antes de una ronda, no a mitad de ella. Gemini está marcado RETIRED: Google cerró Code Assist para cuentas individuales y esa CLI ahora se niega antes de llegar a un modelo. Use Antigravity.",
  },
  "a-local-model": {
    title: "Un modelo en su propia máquina como revisor",
    whatItIs: "Un revisor llamado **local**, respaldado por un motor que corre en esta máquina — Ollama, un vLLM, o cualquier cosa que hable la misma forma compatible con OpenAI. Su lista de modelos es lo que USTED tiene instalado, con el tamaño de parámetros, la cuantización y el tamaño en disco: lo instalado es un hecho sobre su máquina, no una lista que esta extensión pudiera traer consigo.",
    why: "No cuesta nada por ronda y nada sale del edificio. Eso lo convierte en el revisor que puede permitirse en cada push — y el único que puede usar en un cambio que no tiene permiso de enviar a ninguna parte. Es un revisor de OTRA clase que los alojados, no uno más barato: el panel existe para que los mezcle.",
    setup: "Añádalo desde **＋ Add a reviewer** y la fila se completa sola: el motor se busca en 11434 (Ollama) y 8000 (vLLM), y la lista muestra lo que tiene. Si no se encuentra nada, la fila dice dónde buscó y por qué no salió — rechazado, agotó el tiempo, respondió algo raro — en vez de mostrar una lista vacía.\n\nEl campo del endpoint es para todo lo que la búsqueda no ve: un vLLM en otro puerto, una máquina en la red, un motor detrás de un proxy. Quiere la base compatible con OpenAI, terminada en `/v1` — que **no** es la dirección que abriría en un navegador: Ollama sirve su propia API en la raíz y la compatible bajo `/v1`, y una base sin eso falla en la primera revisión con un 404 que se lee como un problema del modelo.\n\n⟳ vuelve a preguntar al motor. Una búsqueda exitosa se cachea un minuto para que el panel no liste modelos en cada repintado — así que un modelo recién descargado todavía no está ahí; ese botón es para eso.",
    usage: "**Déle sitio.** Una revisión es el prompt, el plan o el diff y el esquema, todo en una sola petición. Un modelo con una ventana de contexto pequeña rechaza en lugar de responder mal — honesto, y la ronda se gasta igual. Cuando pueda elegir, tome la variante con más contexto.\n\nEsta fila no tiene ▶, ni ⤓, ni ⟳ de actualización: esos son los botones de una CLI, y aquí no hay nada que iniciar sesión, instalar ni actualizar. Los tokens SÍ se cuentan — el motor los informa y aparecen en el gráfico de gasto — pero el dinero es un guion: un modelo en su propio hardware no tiene factura por tokens. Cuesta electricidad y una tarjeta ocupada, y este panel no ve ninguna de las dos.",
    whatCanGoWrong: "**Un endpoint que no está en esta máquina se anuncia en la fila.** Cada revisión envía allí el prompt — su plan, sus diffs y el contenido de los archivos alrededor. Para eso sirve un motor remoto, y así es también como el código fuente sale del edificio por accidente, por eso la fila nombra el host y lo que va hacia él. Use solo uno que usted controle.\n\n**En una ventana conectada a WSL, a un motor del lado Windows le estorban DOS cosas.** Está atado a `127.0.0.1` — arránquelo con `OLLAMA_HOST=0.0.0.0`; y `127.0.0.1` de este lado es el loopback propio de WSL, no el host Windows, así que el endpoint debe apuntar a la dirección del host Windows.\n\n**Un modelo que el motor ya no lista** se queda en la lista marcado *NOT on this engine any more* — en vez de desaparecer (eso cambiaría su revisor en silencio) o parecer normal (eso enviaría una ronda a un modelo que responde 404).",
  },
  "teach-your-ai": {
    title: "Y: dígale a su IA que use la puerta",
    whatItIs: "Menú ⋯ → **Copy the CLAUDE.md snippet** da un párrafo que se pega en el repositorio que quiere revisar. Le dice a la IA que trabaja allí que existe una puerta de revisión y en qué orden se usa.",
    why: "Un asistente con herramientas pero sin instrucción no se le ocurre abrir una sesión de revisión. Ese párrafo ES la instrucción, y vive en el repositorio y no en la extensión porque es una propiedad del proyecto, no de su editor.",
    setup: "Cópielo, péguelo en el `CLAUDE.md` de ese repositorio (o en lo que lea su asistente) y haga commit. No nombra ningún repositorio: la IA que lo lee ya está dentro de una copia de trabajo que puede nombrar ella misma.",
    usage: "A partir de ahí el asistente abre una sesión, envía el plan, resuelve los hallazgos, implementa, envía el diff y vuelve a resolver. Usted lo observa en **Active rounds** y responde a lo que escale.",
    whatCanGoWrong: "Nada obliga a cumplir ese párrafo. El asistente puede ignorarlo, y la puerta no puede llamarse a sí misma. Lo que SÍ puede es negarse a revisar código mientras el plan no haya pasado, y eso lo hace.",
  },
  "the-gate": {
    title: "La puerta: rondas, el umbral y qué pasa cuando se agotan",
    whatItIs: "Los ajustes que deciden cuándo termina una revisión. **Rounds** es cuántos intentos tiene un ROL. **Passes at or under** es cuántos de sus hallazgos bloqueantes son aceptables. **When the rounds run out** es qué pasa si nunca llega ahí.",
    why: "Sin límite, un bucle de revisión no termina nunca: siempre hay un hallazgo más. El umbral dice con un número qué es «suficiente» antes de que empiece la discusión.",
    setup: "CADA rol tiene sus propias rondas y su propio umbral, y se ajustan junto a los prompts de ese rol: la arquitectura puede merecer dos pasadas con lentes distintas y el rendimiento una, y un presupuesto compartido hace que el rol más barato pague por el más caro. Cada rol de código tiene además una **casilla en su propio encabezado**: sin marcar, el rol no participa en la ronda en absoluto — no se lanza ningún revisor para él, nada de lo que habría encontrado cuenta, y no le presta a la etapa ni sus rondas ni su umbral. Sus números y sus prompts elegidos se conservan y vuelven sin cambios cuando la marque de nuevo. La última no puede desmarcarse: una ronda sin ningún revisor nunca se resuelve. La revisión del plan tiene un rol y no tiene casilla. Un hallazgo cuenta contra el umbral DEL rol que lo levantó, así que un rol ruidoso no puede gastarse la tolerancia de otro. Una etapa pasa cuando cada rol está en su número o por debajo, y solo se revisa para los roles que aún tienen rondas.\n\nAl lado está el otro interruptor, **Deal the lenses across vendors**: apagado, cada proveedor responde la misma pregunta y la coincidencia de dos proveedores es un hecho que la puerta puede usar; encendido, cada lente se pregunta una vez, con la mitad de lanzamientos, y esa coincidencia desaparece.\n\nPor omisión: tres rondas de plan con umbral dos, dos rondas por cada rol de código con umbral tres, reparto apagado y la política *Ask a human*. Al umbral solo cuentan los hallazgos **blocking** y **major**; minor y nit nunca bloquean.\n\nUn hallazgo levantado por dos proveedores cuenta UNA vez. Un hallazgo que usted rechazó con motivo no vuelve a contar hasta que un revisor lo levante con un argumento realmente nuevo.",
    usage: "*Ask a human* es la opción honesta por omisión: la puerta se detiene y pone la decisión delante de usted. *Continue anyway* sigue y dice en voz alta que quedan hallazgos — y no toca ninguno, que es exactamente cómo una puerta se vuelve decoración. *Good enough — take what’s true and move on* es la intermedia: la IA lee los hallazgos abiertos, aplica los que son verdaderos y útiles, rechaza el resto con motivos y sigue. *Escalate* sube una escalera — más esfuerzo del revisor, luego un modelo revisor más fuerte, luego un árbitro más fuerte — y da a la etapa un juego nuevo de rondas cada vez.\n\nTres casillas bajo ese campo no cambian lo que el gate DECIDE: son órdenes que devuelve a la IA que lo llamó, y están apagadas hasta que usted las encienda. **Trabajar de forma autónoma**: a la IA se le dice qué SIGNIFICA autónomo, no sólo que lo sea — cada error recibe una prueba red-green-red; la documentación, el README, el manifiesto y los documentos de módulo se actualizan con cada cambio; TODAS las pruebas se ejecutan antes de una release; donde el repositorio tenga un proceso de release o pull request, se sigue, y los comentarios automáticos de un pull request se leen cinco minutos después y se corrigen; un despliegue automático se verifica contra dev, stage o test y se leen sus logs; el código se relee contra las reglas del repositorio; y la IA dice que trabaja de forma autónoma y qué está escribiendo. Las preguntas que no bloquean se acumulan y se hacen al final, todas juntas; una que sí bloquea se hace de inmediato, pero sólo después de reunir todas las demás bloqueantes, para interrumpirle una sola vez. **Dividir el plan en épicas e historias**: tras aprobarse un plan, se ordena a la IA dividirlo en 2-4 épicas y cada una en 2-4 historias, y cerrar cada historia por completo: revisar el diff aquí, corregir, documentar, probar, hacer commit, y sólo entonces la siguiente. La orden se da una sola vez por asistente: cada épica vuelve para su propia revisión de plan y se le dice que es una PIEZA — constrúyela como una sola unidad y ciérrala bien — en lugar de ordenarle dividir otra vez, lo que no tendría fin. **Dividir con el modelo más fuerte**: la división y las historias caras (pagos, seguridad, arquitectura) van al modelo más fuerte del asistente que llamó, y las ordinarias a su modelo de implementación. Ambos se eligen por tipo de asistente justo debajo del interruptor; para Claude Code son Fable y Opus mientras no los cambie, y a un asistente sin elección se le pide usar su propio modelo más fuerte, nunca el de otro proveedor.",
    whatCanGoWrong: "Un umbral de cero significa que bloquea cualquier hallazgo de cualquier gravedad, lo que en la práctica significa que una revisión no pasa nunca.\n\nLas rondas son por ETAPA: la puerta del plan y la del código reciben cada una la cuenta completa.",
  },
  "prompts-per-round": {
    title: "Prompts por ronda: qué pregunta hace cada ronda",
    whatItIs: "Cada rol de revisor tiene un prompt universal y cinco lentes estrechas. Aquí se elige qué prompt usa cada RONDA de ese rol, y está junto a las rondas y el umbral del mismo rol, porque esos tres ajustes responden juntos a una sola pregunta.\n\nLas últimas doce lentes se midieron antes de entrar aquí: tres redacciones cada una, dos ejecuciones cada una. Las tres redacciones resultaron ser tres FORMAS, y encuentran lo mismo en cantidad; se diferencian en cuánto sobrevive a una segunda ejecución: una lente escrita como tarea (*«ejecútalo dos veces, con un milisegundo de diferencia, y narra ambas»*) se repite a sí misma vez y media más a menudo que la misma pregunta en forma de lista.",
    why: "Un prompt por rol para siempre es la omisión correcta y el techo equivocado. Cuando se le pide a un modelo mirar todo, se reparte fino, y una segunda ronda de la misma pregunta amplia suele devolver las mismas respuestas amplias.",
    setup: "Un selector por ronda por rol; cada opción lleva su propósito como ayuda. Una ronda que no ha tocado muestra lo que el servidor va a ejecutar de verdad para ella — el selector nunca es una suposición ni un prompt que nadie ejecutará.\n\n**La ronda uno de cada rol de CÓDIGO es la pasada de convenciones, salvo que elija otra cosa.** Juzga el diff contra las reglas que este proyecto ha escrito — nada más — y un hallazgo ahí tiene que citar la frase que rompe. Un repositorio sin archivos de reglas cae al prompt universal de ese rol, porque una pasada de convenciones sin convenciones no tiene nada que decir.\n\nCualquier otra ronda sin fijar es la pregunta universal de ese rol. Una lente se pregunta cuando usted la pregunta: ya no hay rotación automática. Hubo una, no le quedaba ningún interruptor al que el panel llegara, y su único efecto restante era que este selector nombraba un prompt que el servidor no ejecutaría.",
    usage: "**Deal the lenses across vendors** es el interruptor junto a estos selectores, y es el que cambia cómo se gasta una ronda: apagado, cada proveedor responde cada pregunta de esa ronda; encendido, los prompts de la ronda se reparten uno por proveedor, y una ronda cuesta un lanzamiento por proveedor en vez de uno por prompt por proveedor. Lo que gasta es el acuerdo: dos proveedores que presentan el mismo hallazgo son la señal más fuerte de este producto, y una ronda repartida no puede producirla. Por eso está apagado por omisión.\n\nCuando de verdad quiera dos lentes distintas sobre un cambio, póngalas en dos rondas y deje correr las dos. Se midió: en dos rondas de código, gastarlas en lentes distintas encontró MENOS hallazgos distintos que hacer dos veces la pregunta universal (17 contra 25), por menos dinero — por eso nada lo hace por usted.\n\nEl texto completo de cada prompt está en **The prompts, in full**.",
    whatCanGoWrong: "**Lo que la medición NO establece.** En tres planes, la unión de tres lentes encontró aproximadamente el doble que cualquiera sola — y ese resultado no sobrevive a su propio control: el MISMO prompt sobre el MISMO texto tres veces dio 6, 4 y 5 hallazgos con solapamientos de 3, 1 y cero. La varianza entre ejecuciones explica sola esa diferencia. Las lentes se ofrecen porque sirven para apuntar, no porque se haya demostrado que encuentran más.",
  },
  "limits": {
    title: "Límites: cuántos a la vez y cuánto se espera a cada uno",
    whatItIs: "**Reviewers at once** limita todo el abanico. **Per vendor** limita a un proveedor. **Reviewer timeout**: cuánto puede tardar un revisor. **Wait for you**: cuánto espera una escalada a una persona antes de rendirse.",
    why: "Una ronda de código son seis procesos que quieren arrancar en el mismo segundo: tres roles por dos proveedores. Sin límite, es justo aquí donde llegan a la vez los límites de procesos del sistema, los ficheros de bloqueo de las propias CLI y los límites de los proveedores — y cada uno parece un timeout mientras no se le llame por su nombre.",
    setup: "Por defecto, tres a la vez y dos por proveedor. El límite por proveedor existe porque el límite de peticiones se cuenta por proveedor: un único límite global gastaría tranquilamente todas las plazas en uno solo.\n\nEl timeout del revisor es de diez minutos. Una ronda de código sobre un diff grande tarda de tres a cinco.",
    usage: "Suba el límite global en una máquina con núcleos libres y bájelo en el portátil en el que además está trabajando. Quien choque contra los límites del proveedor debe bajar precisamente el límite POR PROVEEDOR.",
    whatCanGoWrong: "El timeout mata todo el árbol de procesos, no solo la CLI: los hijos de un revisor no le sobreviven.\n\nQue expire **Wait for you** no es una negativa: la escalada sigue abierta en el panel, y la IA recibe la instrucción de preguntarle en la conversación.",
  },
  "language-and-translator": {
    title: "Idioma: las preguntas van en inglés",
    whatItIs: "Aquí ya no hay nada que ajustar. Una pregunta `call_human` le llega como una frase fija en inglés y tres botones, y su respuesta vuelve exactamente como la dio.",
    why: "Antes había un traductor: la pregunta era prosa que había escrito una IA, había que leerla y usted respondía con sus palabras. Tres botones quitaron todo eso. Un subproceso por escalada que puede expirar, negarse o responder en el idioma equivocado es una pieza móvil que no gana nada.",
    setup: "Nada. Los controles **Ask and answer in** y **Translated by** ya no están, junto con los ajustes `COAI_LANGUAGE` y `COAI_TRANSLATOR_*` que había detrás.",
    usage: "El idioma de ESTA ayuda es aparte y sigue siendo suyo: el selector de la parte superior de estas páginas lo cambia, y se guarda como `coai.helpLanguage`. Lo que cambió es el lado de los revisores, no el de la lectura.",
    whatCanGoWrong: "Aquí ya no puede fallar nada, que era el punto. Si escribe texto libre en un botón que lo permite, llega a la IA sin mediación — vale más que las mismas palabras pasadas a otro idioma por un tercer modelo.",
  },
  "vendor-keys": {
    title: "Claves de proveedor: solo cuando una CLI no sabe autenticarse sola",
    whatItIs: "Una única entrada de tipo `config` en CredsForDevs que guarda una clave por cada proveedor que la necesite. El panel muestra cuál de sus revisores la necesita de verdad.",
    why: "La mayoría de las CLI de revisor ya tienen sesión iniciada en su máquina y no necesitan clave alguna. Quienes sí la necesitan — un endpoint propio, DeepSeek, OpenRouter — no deberían teclearla en un fichero de ajustes.",
    setup: "Solo hace falta si la fila del revisor lo dice. Cree una entrada `config` en CredsForDevs, guarde ahí las claves como `{\"deepseek\": \"sk-…\"}` y pegue su identificador en **CredsForDevs config key**.",
    usage: "El servidor lee la entrada al arrancar y pasa cada clave a su proveedor por el entorno, nunca por la línea de comandos. Cambiar una clave surte efecto en el siguiente arranque del servidor.",
    whatCanGoWrong: "Un proveedor que necesita clave y no la tiene aparece en **providers** como `unavailable` con su motivo y se cae del abanico — no se salta en silencio.",
  },
  "bugz": {
    title: "Bugz: los defectos que su puerta ya encontró",
    whatItIs: "Cada hallazgo ACEPTADO es un defecto que una persona confirmó. **Bugz** los vuelve a leer como material, no como registro: encuentra el método del que trataba, encuentra el commit que lo arregló y guarda el par. **Collect** busca; **Review bugs** es donde usted decidirá qué conservar.",
    why: "Una puerta de revisión produce algo que casi todas las herramientas tiran: pares de código que estuvo mal y luego bien, cada uno confirmado por una persona en vez de adivinado. Medido sobre una base real el 15-09-2026 — 8 687 hallazgos se estrechan a 462 utilizables en 115 historias y 15 repositorios.\n\n**Solo se lee lo que ya está en su máquina.** Los hallazgos vienen de sus propias rondas y el código de su propio historial de git. Recolectar no envía nada a ninguna parte.",
    setup: "Elija un **modelo de clasificación** — solo se ofrecen motores que corren en esta máquina, y eso es una decisión, no cautela: el título y la descripción de un hallazgo son las palabras de los revisores sobre su código, y NO están anonimizadas. El anonimizador actúa después y solo sobre el código fuente. Así que ese paso las lee aquí o no las lee.\n\nLuego pulse **Collect**. La sección muestra la ejecución mientras ocurre y, al terminar, qué hizo con cada candidato.",
    usage: "Una ejecución decide cada hallazgo sin procesar y anota qué decidió: **collected** con el commit que lo arregló, **skipped** con un motivo, o **failed**. Skipped es lo corriente — un lenguaje que aquí nadie analiza; un commit que ninguna rama alcanza ya; un arreglo que no está en este repositorio — y el motivo se conserva, de modo que la tasa es una medición y no un encogimiento de hombros.\n\nLa ejecución se recuerda, así que cerrar la ventana o pulsar F5 cambia lo que USTED VE y nunca lo que ocurrió. Pulse Collect más tarde y tomará los que nadie ha mirado todavía.\n\n**Who holds a key** es la otra mitad: las claves de quienes contribuyen que su servidor de ingesta ha emitido, lo que cada una ha enviado y el botón que termina con una. Ejecute primero **Set the bugs admin key**: se guarda en el almacén de secretos del editor de esta máquina, nunca en la configuración, porque la configuración se sincroniza y una credencial de administración que le sigue a otra máquina es una de la que nadie responde.\n\nUna clave se muestra UNA vez, al emitirse. Si cierra la ventana antes de copiarla, la pestaña se la vuelve a ofrecer la próxima vez y puede revocarla por usted: el servidor no la mostrará una segunda vez. Revocar pregunta antes y nombra la nota de la clave y el mes en que se usó por última vez, porque los identificadores son hexadecimales y se parecen entre sí.\n\n**Send** es el último paso, y el que esta sección no podía dar en absoluto hasta ahora: sube los pares que usted conservó, por el mismo modo de una sola vez que antes se ejecutaba a mano en una terminal. Ejecute primero **Set the bugs contributor key**: una clave distinta de la de administración, guardada en el mismo sitio y por la misma razón.\n\nUn par se marca como enviado solo cuando el servidor dice que lo tiene, así que un envío interrumpido no pierde nada: pulse Send otra vez y los que llegaron se reconocen en lugar de guardarse dos veces. Mientras un envío corre, el botón lo dice, y lo sigue diciendo tras recargar, porque la ejecución queda escrita donde ambas mitades la ven.\n\n**Copias de revisión en esta máquina** es un comando de la paleta y la otra mitad del botón *Extraer <sha> en una ventana nueva* de una fila. Enumera cada copia que ese botón ha hecho aquí — qué repositorio, qué commit, cuándo y si aún sirve —, abre cualquiera de ellas y permite devolver una.\n\nUna eliminación se RECHAZA, con nombres, si la copia contiene algo suyo: un archivo modificado, un archivo nunca confirmado, o cualquiera de los dos dentro de un submódulo — que un status normal ve pero nunca nombra. Los archivos ignorados son el caso que nadie espera (`.env`, una configuración local): se cuentan, se muestran algunos, y solo se van si lo pide una segunda vez.",
    whatCanGoWrong: "**Una ejecución interrumpida lo dice.** Cierre la ventana a mitad y la fila deja de decir que está viva; la próxima vez que alguien pregunte, queda marcada como interrumpida en lugar de parecer que sigue. Lo que ya había decidido se conserva, porque cada candidato se escribió al decidirse.\n\n**Más de la mitad de los commits son inalcanzables, y es normal.** El squash-merge borra la rama en la que corrió una ronda — el 55,7 % de los candidatos medidos — pero los objetos sobreviven, así que el método aún se puede leer y la búsqueda aún se puede acotar con la ronda siguiente de la misma sesión.\n\n**Un modelo que no sea local se rechaza, venga de donde venga.** El panel no ofrecerá ninguno, y el recolector lo rechaza igualmente antes de leer un solo hallazgo: una lista desplegable no es una garantía.",
  },
  "recent-rounds": {
    title: "Active rounds: qué está en marcha ahora mismo",
    whatItIs: "Cada ronda en curso, la más reciente arriba, completa: qué se revisa, la etapa, la rama, cuánto lleva — y debajo cada revisor que la ronda lanzó, con lo que ha hecho hasta ahora, cuántos hallazgos ha presentado, cuánto ha tardado ÉL y qué ha leído.",
    why: "Una revisión tarda minutos, y lo que se espera no es un veredicto sino los revisores que lo producen. Una ronda terminada es otra pregunta — «qué pasó» — y eso es un registro, que pide una tabla con filtros, ordenación y búsqueda, no una barra lateral. Así que la barra lateral se queda solo con el presente.",
    setup: "Nada que configurar. El servidor escribe la ronda en disco al arrancarla y la actualiza a medida que avanzan los revisores, así que la imagen sobrevive a recargar la ventana, reiniciar la extensión y matar el servidor.",
    usage: "No hay nada que pulsar: una ronda en curso ya está abierta, y cuando termina sale de la barra lateral. Todo lo que ha corrido alguna vez — terminado, interrumpido, cada revisor y cada número — está en **Show review rounds** (el menú ⋯ del título del panel).\n\nEse registro contiene también sus CONVERSACIONES, no solo las rondas. La columna **Kind** dice qué es cada fila — *review* o *conversation* — y el filtro contiguo reduce a una o muestra ambas: «cuánto me ha costado hoy» rara vez es una pregunta sobre solo una de ellas. Una conversación deja vacías las columnas de repositorio, rama y etapa: un chat no está atado a una rama.\n\nLa columna **Took** del registro informa de dos tramos de tiempo, no de uno: `2m 10s · 5m 0s` es cuánto corrieron los revisores y, después, cuánto llevó DECIDIR — desde que la ronda terminó hasta su última decisión. Una ronda que nadie ha decidido muestra un solo número, y una conversación también. Una llamada a `resolve` sella con un mismo instante todo lo que toca, así que en una ronda corriente la segunda cifra es la decisión; en una ronda que usted retomó después de comer, la comida cuenta.\n\n**Cada fila termina en Export, y el registro entero puede salir como un fichero.** El **Export** de una ronda escribe un CSV donde usted elija: cuándo corrió, en qué rama y repositorio, su veredicto, de cuántos hallazgos dependía, ambos tiempos, los tokens, las tres cifras de coste y una línea por revisor — y después una línea por HALLAZGO, cada una repitiendo las columnas de la ronda y su decisión sobre él, con las mismas palabras que usa la página (*took*, *declined*, *open*), y el motivo del rechazo al lado.\n\nPara más de una ronda, márquelas. La casilla de la cabecera selecciona todas las rondas que los filtros aceptan en ese momento — en todas las páginas, no solo las veinte de la pantalla — y el botón de la barra dice cuántas ha elegido y cuántas de ellas quedan fuera de vista (*Export 41 selected (3 hidden)…*). Filtrar nunca deshace una selección; **Clear selection** la descarta de un gesto. Una exportación masiva informa de cuántas rondas ha leído y puede cancelarse — si la detiene no se escribe nada — y por encima de quinientas rondas pregunta antes.",
    whatCanGoWrong: "Una ronda abandonada por un servidor caído pasa a *interrupted* en el siguiente arranque y desaparece de aquí; sigue en el registro. Si aquí se lee *Nothing is running* mientras su asistente dice que está revisando, el servidor con el que habla escribe en otro sitio — un `COAI_DATA_DIR` en su configuración que esta ventana no comparte.\n\nEn un fichero exportado, una medición ausente sigue ausente: una ronda cuyos tokens nadie registró deja la celda vacía en lugar de un cero, porque el cero es un número que alguien midió. Una ronda cuyos hallazgos no se pudieron LEER nunca se escribe como una ronda que no encontró nada: la columna `findings_read` lo dice para cada una — *loaded*, *not recorded* o *failed* —, las columnas de hallazgos quedan vacías en los dos últimos casos, y el mensaje posterior a la exportación nombra cada ronda que no pudo leer. Si no se pudo leer nada, no se escribe fichero y el diálogo de guardado no se abre.\n\nNada del fichero puede ejecutarse al abrirlo: una rama o un título que empiece por `=`, `+`, `-` o `@` se escribe como texto, incluso cuando se esconde tras un espacio. El instante se escribe dos veces — tal como se guardó, en UTC, y según el reloj de su máquina indicando el desfase — porque un fichero no puede saber en qué huso se leerá dentro de un año. Cancelar el diálogo de guardado no hace nada y no dice nada; una escritura que falla dice qué falló y nunca afirma haber tenido éxito. Con un `coai-mcp` anterior a esta versión, una exportación masiva sigue funcionando: una ronda cada vez, cuatro a la vez.",
  },
  "what-each-ai-has-used": {
    title: "Qué ha gastado cada IA: tokens, dinero y tiempo",
    whatItIs: "Una barra por proveedor sobre un día, una semana, un mes o un año: tokens de entrada y salida, **dinero**, cuántas ejecuciones, cuántas fallaron, tiempo total y medio — y una línea al final que suma todos los proveedores. Los turnos de chat también se cuentan, y ahora tienen su propia sección en esta pestaña: arriba **Reviewers**, una línea, y debajo **Chat** — una tarjeta por proveedor Y modelo, con la forma de las tarjetas de revisores de arriba, porque una conversación cambia de modelo y un precio pertenece al modelo. Cada tarjeta de chat lleva ambos precios, lo que costó en la ventana elegida, lo que ha costado **en todo el tiempo** sea cual sea la ventana de arriba, y dos contadores: **Asked**, cuántas veces se usaron *take the question* y *add the question*, y **Opened**, cuántas veces se abrió un chat por cualquiera de sus seis puertas. Cada sección suma la suya, porque los dos registros los escriben programas distintos y no deben sumarse a ojo. Bajo ambas secciones, una segunda línea y una fila más suman los dos registros, porque «cuánto me ha costado esto» es una sola pregunta la gastara la mitad del producto que la gastara. En el registro de rondas los turnos de chat siguen apareciendo como filas *conversation*.",
    why: "Un panel de revisión gasta dinero real en cada ronda, y la pregunta «cuánto me ha costado este mes» no se responde desde un archivo de sesión: las sesiones se reescriben conforme avanzan las rondas y guardan una rama cada una.",
    setup: "Para los tokens no hay nada que configurar: el servidor añade una línea por revisor a `usage.jsonl` en su directorio de datos, y esta sección la lee.\n\nPara el DINERO hay una cosa, y solo usted puede darla: **cuánto cobra este proveedor por millón de tokens, de entrada y de salida**, en su propia fila. Este producto no incluye tabla de precios a propósito — una incluida está mal para quien tenga una suscripción plana, mal en cuanto un proveedor cambie un precio, y mal en silencio en ambos casos. Ponga una tarifa y aparece el dinero de ese proveedor; déjela vacía y queda un guion.",
    usage: "**Un revisor que falla también se cuenta.** Una ejecución que quemó noventa segundos y no respondió nada es justo lo que un registro de gasto no debe esconder, así que cada fila lleva su resultado y el número de fallos va junto a los tokens.\n\n**La tilde carga significado.** `$0.42` es lo que cobró un proveedor; `~$0.42` es lo que sale de su propia tarifa. Claude informa su coste, Codex y Antigravity informan solo tokens — así que en esos dos hay tilde o guion, nunca una cifra desnuda. El total mantiene las mitades separadas por lo mismo: se lee `$0.18 + ~$0.31` en vez de sumar un hecho con un cálculo y presentar el resultado como uno de los dos.\n\nPor debajo de un dólar el dinero se muestra con cuatro decimales. Una ronda que costó ocho centésimas de centavo es un número real, y redondearlo a `$0.00` dice que el panel no está contando.",
    whatCanGoWrong: "Los tokens se cuentan por proveedor porque una sola regla sería falsa para al menos uno: Codex mete los tokens en caché DENTRO de la entrada, Claude los informa AL LADO, y en Antigravity los tokens de razonamiento van dentro de la salida. Claude además informa la misma ejecución dos veces con números distintos; se usa el agregado.",
  },
  "questions-waiting": {
    title: "Una pregunta que le espera",
    whatItIs: "Cuando la puerta necesita a una persona, arriba del panel aparece una tarjeta con la pregunta y los hallazgos que siguen bloqueando. Se abre un diálogo, aparece un elemento en la barra de estado y el icono del título se pone verde.",
    why: "Detrás de esa pregunta hay una ronda BLOQUEADA. Una notificación que se puede perder no sirve para esto — de ahí las tres superficies, y cerrar el diálogo no pierde nada.",
    setup: "Para el caso corriente no hay nada que configurar: el servidor escribe la pregunta como fichero en el directorio que la extensión ya vigila, y ninguna de las dos mitades abre un puerto. Un caso sí necesita un ajuste. Una ronda que corre en OTRA instalación —una sesión de Claude Code dentro de WSL, por ejemplo— escribe su pregunta en el directorio de datos de AQUELLA instalación, y una ventana que solo vigila el suyo no la muestra nunca mientras la ronda está bloqueada. `coai.alsoWatchDataDirectories` nombra los otros directorios: las preguntas de otra instalación aparecen junto a las propias y la respuesta se escribe junto a la pregunta, donde mira el servidor que preguntó. Solo se comparten las preguntas; ninguna base de datos se abre a través de la frontera. Desde una ventana de Windows un directorio de WSL debe nombrarse como Windows lo alcanza: `\\\\wsl.localhost\\<distro>\\home\\<user>\\.local\\share\\coai-mcp` — una ruta que empieza por `/` se rechaza explicándolo, en vez de vigilar un directorio que nadie eligió.",
    usage: "Puede responder en el panel, en el diálogo o desde la barra de estado: es la misma acción. La respuesta va a la IA que preguntó, traducida al idioma en que preguntó, y sus propias palabras se conservan al lado.",
    whatCanGoWrong: "El veredicto `call_human` también levanta una tarjeta así, de modo que una puerta con las rondas agotadas le alcanza aunque la IA calle. No siempre fue así: antes el veredicto era una instrucción solo para la IA, y una persona podía mirar el panel todo el día sin enterarse de que la habían llamado.",
  },
  "prompts-in-full": {
    title: "Los prompts, completos",
    whatItIs: "El texto completo de cada prompt que este producto envía a un revisor — los cuatro universales, las ocho lentes estrechas y la pasada de convenciones. Aquí no hay nada parafraseado; esto es lo que lee el modelo.",
    why: "Una revisión que no se puede auditar es una revisión que hay que creer. Saber exactamente qué se preguntó es lo que permite juzgar si una respuesta fue justa — y si un hallazgo con el que no está de acuerdo vino de un modelo malo o de una pregunta mala.",
    setup: "Nada que configurar. Lo impreso abajo se compara con los propios archivos de prompts del servidor mediante un test, así que no puede desviarse de lo que realmente se ejecuta.\n\nEl prompt **conventions** va aparte y no bajo un rol, porque no es una lente sobre la pregunta de un rol: es otra pregunta que los tres roles de código hacen en la ronda uno. Las reglas llegan con él — los propios `CLAUDE.md`, `AGENTS.md`, `GEMINI.md` y `.claude/rules` del proyecto, leídos del worktree del commit revisado y citados literalmente, hasta 40 KB, y lo que quede fuera se nombra en vez de descartarse en silencio.",
    usage: "Cada prompt termina con la misma disciplina: un hallazgo debe nombrar una situación concreta y el resultado equivocado que produce; cuatro clases de no-hallazgo están nombradas y prohibidas; y se dice expresamente que una lista de hallazgos vacía es una respuesta válida — a un revisor al que se le dice que siempre encuentre algo, siempre encontrará algo.\n\nPuede sobrescribir cualquiera: deje un archivo con el nombre del prompt en `prompts/` dentro del directorio de datos del servidor y gana mientras exista. Bórrelo y vuelve el texto de fábrica.",
    whatCanGoWrong: "Una sobrescritura no se valida. Un prompt que no pide el esquema de hallazgos producirá respuestas que no se pueden parsear, y la ronda informará de ese revisor como no parseable — guardando su respuesta cruda en disco para que vea qué pidió.",
  },
  "the-help-page": {
    title: "Esta página: búsqueda, idioma y tamaño del texto",
    whatItIs: "El ? amarillo del título del panel abre esta ayuda. La lista muestra cada artículo con su primera línea; el campo de arriba busca en todos; el desplegable cambia el idioma; los botones ± cambian el tamaño del texto, y el par de al lado el tono del texto: más claro, o más apagado y cálido.",
    why: "Un panel de ajustes con dieciséis elementos necesita un sitio donde se diga qué hace cada uno — un tooltip no sirve. El tamaño del texto está aquí porque la vista no es materia de discusión: cinco pasos en cada sentido son aproximadamente ×1,6 arriba o abajo.",
    setup: "Nada que configurar. El selector de idioma escribe `coai.helpLanguage` y solo afecta a estas páginas — no es el idioma en el que se pregunta a sus revisores, ese está en la sección **Language**. Los botones ± escriben `coai.uiScale` y `coai.textTone`; el cero del tono es el color de su propio tema, así que un control sin tocar no cambia nada. Ambos son ajustes reales, así que se sincronizan con sus otras máquinas.",
    usage: "La búsqueda recorre los títulos Y el texto completo de cada artículo en el idioma mostrado, así que una palabra que recuerde de un párrafo encuentra el artículo donde estaba. Escape cierra un artículo y vuelve a la lista, y Back conserva lo escrito.\n\nUn artículo sin traducir muestra el inglés con una nota visible, no una página en blanco.",
    whatCanGoWrong: "Que una traducción vaya por detrás del inglés es normal y se señala. Lo que no puede pasar es que falte un artículo: un test de cobertura tumba la compilación cuando de un comando o un ajuste no hay nada escrito. Justo por eso esta página no puede convertirse en silencio en la descripción de un producto que ya no existe.",
  },
  "the-protocol": {
    title: "Bajo el capó: el protocolo que sigue su IA",
    whatItIs: "Nueve herramientas en orden estricto. `open` abre una sesión para un repositorio y una rama. `review_plan` envía el plan a todos los revisores. `resolve` registra la aceptación o el rechazo de CADA hallazgo. `review_code` hace lo mismo con el diff, con cuatro roles por proveedor. `review_document` es la otra puerta: un DOCUMENTO en lugar de un diff, sin ronda de plan antes y con su propia sesión por documento. `providers` muestra el estado, `status` devuelve al contexto una conversación reanudada, y `ask_human` escala hasta usted. `consult` es la novena y la única que no bloquea nada: un asistente atascado pregunta al modelo de otro proveedor sobre su árbol de trabajo tal como está, y recibe una respuesta en lugar de un veredicto.",
    why: "El orden se sostiene por rechazo, no por buena conducta: `review_code` se niega mientras ninguna ronda de plan haya llegado a *proceed*, de modo que saltarse una etapa es imposible, no «desaconsejable».",
    setup: "Nada que configurar: esto lo maneja su IA. El orden se lo dice justo el fragmento que usted pegó en el repositorio.",
    usage: "Un rechazo exige un motivo, y el motivo se conserva: un hallazgo rechazado no cuenta en las siguientes rondas hasta que un revisor lo vuelva a plantear con un argumento nuevo. Eso es lo que impide que el bucle reabra una decisión que usted ya tomó.",
    whatCanGoWrong: "Una ronda en la que no respondió NADIE no pasa nunca. Un resultado vacío es ausencia de evidencia, no evidencia de ausencia: la puerta llama a una persona en su lugar. Es el único caso en el que «sin hallazgos» no debe significar «aprobado».",
  },
  "where-reviewers-run": {
    title: "Bajo el capó: dónde se ejecuta realmente un revisor",
    whatItIs: "La etapa de código da a la ronda UN git-worktree, fijado al commit de la rama, solo lectura. La etapa de plan da en cambio a cada revisor un directorio VACÍO.",
    why: "Si a una CLI agéntica se le da un repositorio y un plan que menciona ficheros, va a leerlos. Medido: ocho minutos y aún ejecutándose — sobre un documento de quince kilobytes. Ahí el papel es juzgar el DOCUMENTO; el repositorio lo necesita la etapa de código.",
    setup: "Nada que configurar. Los worktrees viven en el directorio de datos del servidor y se limpian al abrir una sesión, así que una ronda abortada no deja nada detrás.",
    usage: "Lo que cuesta el directorio vacío, sin rodeos: un revisor de plan no puede comprobar que una referencia del tipo `file.cs:line` sea real. Esa comprobación nunca estuvo en el prompt del plan, y comprarla al precio de diez veces el tiempo es el cambio equivocado para una puerta en la que hay una persona esperando.",
    whatCanGoWrong: "El único reintento de un revisor también se ejecuta en un directorio vacío, por la misma razón: la reparación pide la respuesta con el esquema, no una investigación nueva. Precisamente volver a entregarle un checkout costaba un revisor en una de cada tres rondas de código.",
  },
  "when-a-reviewer-fails": {
    title: "Bajo el capó: qué pasa cuando un revisor falla",
    whatItIs: "Seis desenlaces con nombre, y nunca un cero silencioso: respondió, agotó el tiempo, terminó con código distinto de cero, chocó con un límite, no pudo arrancar, o respondió algo que no se puede parsear. Una ronda que pasó con cuatro revisores de seis lo dice así, con nombres.",
    why: "Un panel que no revisó no es un panel que aprobó. Cada ronda incompleta se informa como incompleta, y la frase sobre los revisores nombra quién falló y por qué.",
    setup: "Nada que configurar. Un revisor con límite de peticiones se reintenta una sola vez tras una pausa — salvo que el proveedor haya dicho que el límite es DIARIO, y eso no lo cura ningún reintento.",
    usage: "Una negativa lleva las propias palabras de la CLI, elegidas por contenido y no por posición: la primera línea que anuncia un error, saltándose los marcos de pila y los banners de versión. Para cinco negativas conocidas — CLI cerrada, directorio no confiable, binario ausente para la plataforma — se dice QUÉ HACER, no qué se imprimió.",
    whatCanGoWrong: "Una respuesta que no se pudo parsear se guarda en disco bajo `unparseable/` dentro del directorio de datos, y la negativa nombra el fichero. Esto nació porque esa misma respuesta, reproducida a mano, pasaba sin problemas: el mensaje nombraba un síntoma imposible de investigar.",
  },
  "settings-and-the-server": {
    title: "Bajo el capó: cómo llega un ajuste al servidor",
    whatItIs: "El panel escribe sus ajustes en un fichero dentro del directorio de datos del servidor, y el servidor relee ese fichero cada vez que cambia.",
    why: "Antes los ajustes llegaban al servidor solo dentro del bloque de configuración pegado, y cambiar un umbral se convertía en un trámite: copiar el bloque, encontrar la configuración del cliente, pegar, reiniciar. Y solo se aplicaban al arrancar — una brecha invisible desde ambos lados, porque el panel guarda al instante y así lo dice.",
    setup: "Nada que configurar. Un cambio en el panel rige desde la SIGUIENTE ronda: ni reinicio ni volver a pegar.",
    usage: "Una variable puesta en la configuración del propio asistente sigue ganando al fichero: es más específica que un fichero que cualquier ventana puede reescribir.\n\nEl panel escribe solo lo que DIFIERE de los valores por defecto, así que devolver un ajuste a su valor por defecto lo quita del fichero en vez de fijarlo.",
    whatCanGoWrong: "Un fichero a medio escribir deja en pie la última configuración que funcionaba. Una lectura rota que diera una lista de proveedores vacía habría hecho fallar a todos los revisores y lo habría informado un panel de acuerdo consigo mismo.\n\nAjustes separados por lado: una máquina puede tener varios entornos de trabajo - una ventana local y una o varias distribuciones de WSL - y VS Code les entrega el MISMO archivo de ajustes. Active el interruptor y cada lado conserva sus propios valores, sembrados con lo que tenía en ese momento, de modo que nada cambia hasta que edite algo. Para una persona que trabaja para dos empresas en una máquina, eso significa un proxy distinto, una ruta de CLI distinta y una clave de bóveda distinta por lado. El tamaño del texto y el idioma de la ayuda siguen siendo comunes: le pertenecen a usted, no al trabajo.",
  },
  "the-audit-log": {
    title: "Bajo el capó: el registro de auditoría",
    whatItIs: "Un fichero de log por arranque del servidor, en `logs/<día>/` dentro de la misma carpeta donde el servidor guarda todo lo demás — vea *Dónde viven sus datos*. Contiene el reparto de cada ronda, el arranque y la respuesta de cada revisor con tokens y dinero, cada negativa como aviso con su motivo, y cada hallazgo con su procedencia.",
    why: "El resumen de una ronda es deliberadamente una frase, y una frase no responde a «por qué falló ese revisor». Esa pregunta surgió dos veces en una puerta real, y las dos veces no había nada que responder.",
    setup: "Nada que configurar. Los niveles vienen de la configuración y no de los puntos de llamada, y cada arranque escribe un fichero nuevo — no uno por día, porque casi siempre se pregunta qué hizo AQUELLA ejecución.",
    usage: "En nivel debug se escribe la línea de comandos exacta de cada revisor: esa es la diferencia entre «saber que se preguntó al proveedor» y «pegar el comando en una terminal y ver la misma negativa».",
    whatCanGoWrong: "El log es el único sitio donde algunas cosas quedan registradas. No rota ni se recorta: un año de trabajo denso es una carpeta de ficheros pequeños — no es un problema, pero limpiarla le toca a usted.",
  },
  "where-your-data-lives": {
    title: "Dónde viven sus datos, y cómo conservarlos",
    whatItIs: "Una carpeta guarda todo lo que este producto recuerda: la base de datos de rondas, las sesiones, sus chats con sus imágenes, los prompts que editó, el libro de gastos y los registros de auditoría. Por defecto es `%LOCALAPPDATA%\\coai-mcp` en Windows y `~/.local/share/coai-mcp` en el resto. La sección *MCP server* del panel nombra la carpeta que lee esta ventana.",
    why: "La carpeta por defecto vive en el disco del sistema, y el disco del sistema es justo lo que se formatea. Apúntela a una unidad de red o a un NAS y su historial sobrevive al sistema operativo que tiene encima: reinstala, instala de nuevo el servidor MCP, elige la misma carpeta, y todas las rondas que ha hecho siguen ahí. La misma carpeta pueden compartirla una ventana de Windows y otra de WSL en la misma máquina.",
    setup: "La instalación del servidor MCP pregunta, la primera vez en cada lado de una máquina: conservar la carpeta por defecto o elegir una. Elegir una carpeta que ya contiene una base de datos la ADOPTA — de eso se trata, y así una máquina reinstalada recupera su propio historial. También puede fijarlo usted en Configuración: `coai.dataDirectory` para la carpeta y `coai.dataSide` para el nombre de esta instalación dentro de ella. Ambos se guardan por lado de la máquina, porque el mismo NAS es `Z:\\coai` en una ventana de Windows y `/mnt/z/coai` en una de WSL. Después la sección *MCP server* del panel lleva un botón **Change where your data lives**, y la paleta de comandos tiene la misma entrada.",
    usage: "Un servidor solo conoce la carpeta por la entrada de cliente que lo arranca, así que el bloque que *Install the MCP server…* copia a su portapapeles ya la lleva: péguelo una vez, reinicie su asistente, y ambas mitades leen el mismo sitio.\n\nDé un nombre a un lado cuando dos instalaciones comparten una carpeta: cada una guarda dentro su propia base de datos, sus sesiones y sus inicios de sesión. Déjelo vacío cuando solo esta instalación usa esa carpeta.",
    whatCanGoWrong: "El panel y el servidor pueden acabar leyendo carpetas distintas — eso es lo que significa una lista de rondas vacía mientras su asistente dice que está revisando. La sección nombra la carpeta que lee ESTA VENTANA y entrega las dos líneas que hacen que un servidor coincida con ella.\n\nUn nombre de lado puede llevar minúsculas, dígitos, punto, guion y guion bajo. Cualquier otra cosa se rechaza en vez de ignorarse en silencio, y el servidor no arranca con ella: volver a la carpeta compartida pondría todas las instalaciones sobre una sola base de datos, lo contrario de para lo que sirve un lado.\n\nMudar una carpeta que ya tiene cosas es una copia que se hace con nada en marcha, y es más que la base de datos: las sesiones, los chats y sus libros, los prompts que editó, el libro de gastos y los registros de auditoría y los logs se mudan con ella — con una excepción: si le ha dado un nombre de lado a esta instalación, el servidor escribe sus logs en la carpeta SUPERIOR al lado, así que una mudanza no los alcanza y lo dice antes de empezar. Deje atrás los worktrees temporales y los tokens de sesión — un token pertenece al lado que lo obtuvo.\n\n**Move your data to another folder** hace esa copia por usted: se niega mientras algo siga escribiendo, se niega ante una carpeta que ya tiene una historia propia, copia, y luego vuelve a leer la carpeta nueva y la compara con la vieja antes de apuntar esta ventana allí. No borra nada. **Delete the old data folder** es una acción aparte, y sigue negada hasta que una mudanza cuadre: una copia que no cuadró es una copia para la que la carpeta vieja puede ser el único sitio donde algo aún existe.",
  },
};
